  type TerminalSessionRuntimesProps,
} from './TerminalSessionRuntimes'

export function TerminalDeck({
  deckRef,
  label,
  visible,
  presentationVisible,
  available,
  ready,
  sessions,
  providers,
  activeId,
  primaryActiveId,
  secondaryActiveId,
  split,
  primaryWidth,
  terminalTheme,
  terminalLightThemeId,
